<?phpsession_start();header("Cache-Control: no-store, no-cache, must-revalidate");header("Pragma: no-cache");header("Expires: 0");require_once '../config/db.php';// Authorization - sirf owner yahan aa sakta haiif (!isset($_SESSION['user_id']) || $_SESSION['user_role'] != 'owner') {    header("Location: ../auth/login.php");    exit();}// Sirf is owner ki properties lo$stmt = $pdo->prepare("SELECT * FROM properties WHERE user_id = ?");$stmt->execute([$_SESSION['user_id']]);$properties = $stmt->fetchAll(PDO::FETCH_ASSOC);?><!DOCTYPE html><html lang="en"><head>    <meta charset="UTF-8">    <title>Owner Dashboard - KirayaHub</title>    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><nav class="navbar navbar-dark bg-dark px-4">    <span class="navbar-brand d-flex align-items-center">        <svg width="28" height="28" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" class="me-2">            <polygon points="50,10 90,45 80,45 80,90 20,90 20,45 10,45" fill="white"/>            <rect x="38" y="60" width="24" height="30" fill="#4a4a8a"/>            <rect x="55" y="48" width="15" height="15" fill="#1a1a2e"/>        </svg>        KirayaHub    </span>    <div>        <span class="text-white me-3">Welcome, <?php echo $_SESSION['user_name']; ?></span>        <a href="../auth/logout.php" class="btn btn-outline-light btn-sm">Logout</a>    </div></nav><div class="container mt-4">    <div class="d-flex justify-content-between align-items-center mb-3">        <h4>My Properties</h4>        <a href="add_property.php" class="btn btn-success">Add New Property</a>    </div>    <?php if (count($properties) == 0): ?>        <div class="alert alert-info">No properties added yet.</div>    <?php else: ?>        <div class="row">            <?php foreach ($properties as $property): ?>                <div class="col-md-4 mb-3">                    <div class="card shadow-sm">                        <?php if ($property['image']): ?>                            <img src="../uploads/<?php echo $property['image']; ?>"                                 class="card-img-top" style="height:200px; object-fit:cover;">                        <?php endif; ?>                        <div class="card-body">                            <h5 class="card-title"><?php echo $property['title']; ?></h5>                            <p class="card-text">                                Location: <?php echo $property['location']; ?><br>                                Rent: Rs. <?php echo $property['rent']; ?>/month<br>                                Rooms: <?php echo $property['rooms']; ?><br>                                Contact: <?php echo $property['contact']; ?><br>                                Status: <span class="badge bg-success"><?php echo $property['status']; ?></span>                            </p>                            <a href="requests.php?property_id=<?php echo $property['id']; ?>"                               class="btn btn-primary btn-sm">View Requests</a>                        </div>                    </div>                </div>            <?php endforeach; ?>        </div>    <?php endif; ?></div></body></html>